styl:
.white-bg.b-system-text-56 {  background:#fff  }
.b-system-text-56 table[class=body] table.columns td.first-td {  max-width:100%;height:40px;vertical-align:middle;padding-left:20px;padding-right:20px;border:1px solid #5b6e88;padding-bottom:0!important;border-collapse:collapse  }
@media screen and (max-width:600px) {
  .b-system-text-56 table[class=body] table.columns td.first-td {  padding-left:10px!important;padding-right:10px!important;width:150px!important  }
}
.b-system-text-56 table[class=body] table.columns td.last-td {  max-width:100%;height:40px;line-height:40px;vertical-align:middle;padding-left:20px;padding-right:20px;border:1px solid #5b6e88;padding-bottom:0!important;border-collapse:collapse  }
@media screen and (max-width:600px) {
  .b-system-text-56 table[class=body] table.columns td.last-td {  padding-left:10px!important;padding-right:10px!important;width:150px!important  }
}
.b-system-text-56 .table-title {  color:#5b6e88;font-size:16px;font-weight:700;padding:10px 0  }
.b-system-text-56 .asterisk, .b-system-text-56 .table-text {  color:#5b6e88;font-size:16px;font-weight:400  }
